	`retention_days` smallint unsigned,
	`honeypot_enabled` boolean NOT NULL DEFAULT true,
	`min_fill_seconds` tinyint unsigned NOT NULL DEFAULT 3,
	`consent_mode` enum('notice','checkbox') NOT NULL DEFAULT 'notice',
	`accept_files` boolean NOT NULL DEFAULT false,
	`max_files` tinyint unsigned NOT NULL DEFAULT 5,
	`max_file_mb` tinyint unsigned NOT NULL DEFAULT 10,
	`accepted_extensions` varchar(200) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '.pdf,.jpg,.jpeg,.png',
	`publication_status` enum('unpublished','published','archived') NOT NULL DEFAULT 'unpublished',
	`draft_status` enum('none','draft','in_review') NOT NULL DEFAULT 'draft',
	`published_revision_id` char(26) CHARACTER SET ascii COLLATE ascii_bin,
	`current_revision_id` char(26) CHARACTER SET ascii COLLATE ascii_bin,
	`lock_version` int unsigned NOT NULL DEFAULT 0,
	`first_published_at` datetime(3),
	`published_at` datetime(3),
	`published_by` char(26) CHARACTER SET ascii COLLATE ascii_bin,
	`archived_at` datetime(3),
	`archived_by` char(26) CHARACTER SET ascii COLLATE ascii_bin,
	`created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	`created_by` char(26) CHARACTER SET ascii COLLATE ascii_bin,
	`updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	`updated_by` char(26) CHARACTER SET ascii COLLATE ascii_bin,
	CONSTRAINT `forms_id` PRIMARY KEY(`id`),
	CONSTRAINT `uq_forms_key` UNIQUE(`key`),
	CONSTRAINT `ck_forms_live` CHECK(`forms`.`publication_status` <> 'published' OR `forms`.`published_revision_id` IS NOT NULL),
	CONSTRAINT `ck_forms_archived` CHECK(`forms`.`publication_status` <> 'archived' OR `forms`.`draft_status` = 'none'),
	CONSTRAINT `ck_forms_key` CHECK(`forms`.`key` REGEXP '^[a-z][a-z0-9_]{0,31}$'),
	CONSTRAINT `ck_forms_retention` CHECK(`forms`.`retention_days` IS NULL OR `forms`.`retention_days` BETWEEN 30 AND 3650),
	CONSTRAINT `ck_forms_min_fill` CHECK(`forms`.`min_fill_seconds` BETWEEN 1 AND 60),
	CONSTRAINT `ck_forms_max_files` CHECK(`forms`.`max_files` BETWEEN 1 AND 5),
	CONSTRAINT `ck_forms_max_file_mb` CHECK(`forms`.`max_file_mb` BETWEEN 1 AND 10)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
